    elif operation == "multiply":
        return a * b
    elif operation == "divide":
        return a / b
    elif operation == "power":
        return a ** b
    elif operation == "modulo":
        return a % b
```

2. Get the current date and time:

```python
import datetime

def get_current_time(timezone_name="UTC"):
    current_time = datetime.datetime.now(datetime.timezone.utc).astimezone(datetime.timezone(timedelta(hours=timezone_name)))
