    if n <= 0:
        return "Invalid input. Please provide a positive integer between 1 and 50."
    elif n == 1:
        return "The first Fibonacci number is 1."
    elif n == 2:
        return "The second Fibonacci number is 1."
    else:
        fib_sequence = [1, 1]
        for i in range(2, n):
            fib_sequence.append(fib_sequence[i - 1] + fib_sequence[i - 2])
        return fib_sequence[n - 1]
